// Presentation metadata only. The codec remains the authority for byte edits.
const AREAS={Resources:'◈',Modules:'▦',Workshop:'⚒',Factory:'⚙',Laboratory:'⚗','Tower Testing':'♜','Power Plant':'ϟ',Mine:'◇',Headquarters:'⌂',Arcade:'♟','Perfect Space':'✦',Adventure:'♧',Museum:'▣',Artifacts:'◆','Trading cards':'▤','Trading Post':'⇄',Shipyard:'⚓','Construction Firm':'▧',Town:'⌂',Achievements:'★',Statistics:'▥',Events:'❄',Settings:'☷','Other progress':'…','All fields':'⌕'};
const categories=['All fields','Resources','Modules','Workshop','Factory','Laboratory','Tower Testing','Power Plant','Mine','Headquarters','Arcade','Perfect Space','Adventure','Museum','Artifacts','Trading cards','Trading Post','Shipyard','Construction Firm','Town','Achievements','Statistics','Events','Settings','Other progress'];
function moduleId(f){const m=f.path.match(/(?:^|\/)modules\/([^/]+)\/(?:level|tier|freeTiers|unlocked)$/);if(m)return m[1];const m2=f.path.match(/^([^/]+)\/(?:level|tier|freeTiers|unlocked)$/);return m2&&MODULE_META[m2[1]]?m2[1]:null}
function group(f){const p=f.path.toLowerCase(),r=p.split('/')[0];if(moduleId(f))return 'Modules';if(/^user\/(round|era|infinity|tower|speedmode)/.test(p))return 'Tower Testing';if(/^user\/(ui|uuid|credits)/.test(p))return 'Settings';if(r==='currencystacks')return 'Resources';if(p.includes('adventure/'))return 'Adventure';if(p.includes('perfectspace/'))return 'Perfect Space';if(r.includes('tradingcard'))return 'Trading cards';const roots={workshop:'Workshop',factory:'Factory',items:'Factory',fabricator:'Factory',trees:'Factory',laboratory:'Laboratory',sciencefunds:'Laboratory',fire:'Laboratory',water:'Laboratory',nature:'Laboratory',earth:'Laboratory',electricity:'Laboratory',darkness:'Laboratory',light:'Laboratory',air:'Laboratory',neutral:'Laboratory',universal:'Laboratory',towertesting:'Tower Testing',challenges:'Tower Testing',gamemodes:'Tower Testing',idle:'Tower Testing',bosses:'Tower Testing',powerplant:'Power Plant',mine:'Mine',headquarters:'Headquarters',arcade:'Arcade',museum:'Museum',artifacts:'Artifacts',achievements:'Achievements',tradingpost:'Trading Post',shipyard:'Shipyard',constructionfirm:'Construction Firm',town:'Town',townassets:'Town',buildings:'Town',workers:'Town',statueofcubos:'Town',statistics:'Statistics',statisticgoals:'Statistics',options:'Settings',advancedoptions:'Settings',input:'Settings',weather:'Settings'};if(roots[r])return roots[r];if(/^(pumpkin|graves|bats|castle|cauldron|presents|reindeers|calendar)(\.|$)/.test(r))return 'Events';if(/^(solarpanel|pipe|steam|plasma|lava|coal|oil|gas|helium3|uranium|water[tT]urbine|fusion|fission|wind|yellowbattery|redbattery|bluebattery|spaceelevator|drone)/i.test(r))return 'Power Plant';if(/(?:fastermachines|fullcapacity|craftingautofill|advancedrefining|moreores|infiniterubber|machinehandling|chemicallumps|battleproducers)/.test(r))return 'Factory';if(/(?:overpaidinterns|elementalcores|modulemolecules|breakthrough|scoping|fundamentals|forces|universaltheorem)/.test(r))return 'Laboratory';if(/(?:detector|deepmining|offlinemining|advanceddrill|tankexpansion|collapsingtunnels|mineralogy|geology|battledrills|asteroiddrill|scanner)/.test(r))return 'Mine';return 'Other progress'}
function locationOf(f){if(group(f)==='Modules')return 'Workshop';if(group(f)==='Resources'){const k=f.path.split('/')[1]?.toLowerCase();return categories.find(c=>c.toLowerCase().replace(/ /g,'')===k)||'Resources'}return group(f)}
function states(f){const p=f.path.toLowerCase();if(p.includes('/hints/'))return ['Revealed','Hidden'];if(/unlocked$/.test(p))return ['Unlocked','Locked'];if(/researched$/.test(p))return ['Researched','Not researched'];if(/claimed$/.test(p))return ['Claimed','Unclaimed'];if(/defeated$/.test(p))return ['Defeated','Not defeated'];if(/complete[d]?$/.test(p))return ['Completed','Incomplete'];if(/isinfinite$/.test(p))return ['Unlimited','Limited'];if(/active$/.test(p))return ['Active','Inactive'];return ['Enabled','Disabled']}
function valueText(v,f){return typeof v==='boolean'?(f?states(f)[v?0:1]:v?'Enabled':'Disabled'):String(v)}
function modType(f){return MODULE_META[moduleId(f)]?.type||'Unclassified'}
function searchText(f){return [f.path,pretty(f.path),group(f),locationOf(f),moduleId(f)?modType(f):'',group(f)==='Laboratory'?'lab experiments research':'',group(f)==='Resources'?'currency money balance':'',f.path.includes('gameTokens')?'arcade tokens':''].join(' ').toLowerCase()}
function shown(){const q=$('search').value.toLowerCase().trim().split(/\s+/).filter(Boolean);return fields.filter(f=>(category==='All fields'||group(f)===category||(category==='Workshop'&&group(f)==='Modules'))&&(!$('location').value||locationOf(f)===$('location').value)&&(!$('moduleType').value||moduleId(f)&&modType(f)===$('moduleType').value)&&(!$('fieldKind').value||($('fieldKind').value==='boolean'?f.type===12:$('fieldKind').value==='number'?![11,12].includes(f.type):f.type===11))&&(!$('stateFilter').value||(f.type===12&&String(edits.get(f.offset)?.after??f.value)===$('stateFilter').value))&&q.every(w=>searchText(f).includes(w))&&(!$('changedOnly').checked||edits.has(f.offset))).sort((a,b)=>{const mode=$('sortBy').value;if(mode==='type')return modType(a).localeCompare(modType(b))||a.path.localeCompare(b.path);if(mode==='changed')return Number(edits.has(b.offset))-Number(edits.has(a.offset))||a.path.localeCompare(b.path);if(mode==='name-desc')return b.path.localeCompare(a.path);return info(a).section.localeCompare(info(b).section)||info(a).name.localeCompare(info(b).name)})}
function clearFilters(){for(const id of ['search','location','moduleType','fieldKind','stateFilter'])$(id).value='';$('changedOnly').checked=false;page=0}
let bulkPlan=[],lastBulk=null;
function bulkTargets(){const source=$('bulkScope').value==='all'?fields.filter(f=>moduleId(f)):shown().filter(f=>moduleId(f));const property=$('bulkAction').value==='lock'||$('bulkAction').value==='unlock'?'unlocked':$('bulkAction').value;return source.filter(f=>f.path.split('/').at(-1)===property)}
function previewBulk(){try{const targets=bulkTargets(),action=$('bulkAction').value,v=action==='unlock'?true:action==='lock'?false:$('bulkValue').value;if(!targets.length)throw Error('No matching module fields. Choose another scope or clear filters.');if(!['unlock','lock'].includes(action)&&(!Number.isInteger(Number(v))||Number(v)<0||String(v).trim()===''))throw Error('Enter a non-negative whole number.');bulkPlan=targets.map(f=>({...f,after:v,bytes:S.serialize(f,v)}));$('bulkPreview').textContent=`${targets.length} modules across all pages · ${pretty(action)} → ${typeof v==='boolean'?v?'Unlocked':'Locked':v}. `+targets.slice(0,4).map(f=>pretty(moduleId(f))).join(', ')+(targets.length>4?', …':'');$('bulkConfirm').disabled=false;message('Preview ready. Apply to stage these changes.')}catch(e){bulkPlan=[];$('bulkConfirm').disabled=true;message(e.message,true)}}
function applyBulk(){if(!bulkPlan.length)return;try{const trial=new Map(edits);for(const e of bulkPlan){const orig=save.data.slice(e.offset,e.end);if(e.bytes.length===orig.length&&e.bytes.every((v,i)=>v===orig[i]))trial.delete(e.offset);else trial.set(e.offset,e)}S.patch(save.data,trial.values());lastBulk=new Map(edits);edits=trial;const count=bulkPlan.length;invalidateBulk();render();message(`${count} module settings applied across all pages. Review changes or undo the batch.`)}catch(e){message(e.message,true)}}
function invalidateBulk(){bulkPlan=[];$('bulkConfirm').disabled=true;$('bulkPreview').textContent='Preview shows the exact number of affected modules before applying.'}
function setupFilters(){for(const c of categories.filter(c=>!['All fields','Modules'].includes(c))){const o=document.createElement('option');o.value=c;o.textContent=c;$('location').append(o)}for(const t of ['Offensive','Defensive','Utility','Ultimate','Legendary','Special','Unclassified']){const o=document.createElement('option');o.value=t;o.textContent=t;$('moduleType').append(o)}for(const id of ['location','moduleType','fieldKind','stateFilter','sortBy'])$(id).onchange=()=>{if(id==='location'&&$('location').value)category='All fields';if(id==='moduleType'&&$('moduleType').value){category='Modules';$('location').value=''}page=0;invalidateBulk();render()};$('clearFilters').onclick=()=>{clearFilters();invalidateBulk();render()};$('searchAll').onclick=()=>{category='All fields';$('location').value='';$('moduleType').value='';page=0;invalidateBulk();render()};$('bulkPreviewButton').onclick=previewBulk;$('bulkConfirm').onclick=applyBulk;$('bulkUndo').onclick=()=>{if(lastBulk){edits=lastBulk;lastBulk=null;invalidateBulk();render();message('Restored the changes staged before the last bulk action.')}};for(const id of ['bulkScope','bulkAction','bulkValue'])$(id).oninput=$(id).onchange=()=>{invalidateBulk();$('bulkValue').hidden=['unlock','lock'].includes($('bulkAction').value)}}
